<script>
  import { onDestroy, onMount } from 'svelte'

  const {
    class: klass = '', // Allows you to specify portal class
    target = null, // CSS Selector
    children,
    ...rest
  } = $props()

  let portal
  let portalParent

  // There's a strange effect: When elements are portalled away, they lose the ability to use onclick and other Svelte related stuff
  // Known problem: When moving elements with portals, event listeners on Svelte components stop working. To combat this, add a ref and then add event listeners accordingly.

  onMount(() => {
    portalParent = target ? document.querySelector(target) : document.body
    portalParent.append(portal)
  })

  onDestroy(() => {
    if (!portalParent) return
    portalParent.removeChild(portal)
  })
</script>

<div {...rest} class="portal {klass}" bind:this={portal}>
  {@render children()}
</div>
